#' Ridgeline (green-blue-red)
#'
#' 
#' @param data .
#' @param vars .
#' @param orientation .
#' @param sortVars .
#' @param useDesc .
#' @param transform .
#' @param invertVars .
#' @param reversePalette .
#' @param plotTheme .
#' @param textSize .
#' @param alpha .
#' @param lineWidth .
#' @param valueLabel .
#' @param title .
#' @param showN .
#' @param ridgeOverlap .
#' @param ridgeAdjust .
#' @param ridgeTrim .
#' @param ridgeMedian .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$hint} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot_ridge} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
distRidge <- function(
    data,
    vars,
    orientation = "horizontal",
    sortVars = "none",
    useDesc = FALSE,
    transform = "none",
    invertVars = FALSE,
    reversePalette = FALSE,
    plotTheme = "jamovi",
    textSize = 16,
    alpha = 80,
    lineWidth = 2,
    valueLabel = "Value",
    title = "",
    showN = FALSE,
    ridgeOverlap = 50,
    ridgeAdjust = 1,
    ridgeTrim = FALSE,
    ridgeMedian = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("distRidge requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))


    options <- distRidgeOptions$new(
        vars = vars,
        orientation = orientation,
        sortVars = sortVars,
        useDesc = useDesc,
        transform = transform,
        invertVars = invertVars,
        reversePalette = reversePalette,
        plotTheme = plotTheme,
        textSize = textSize,
        alpha = alpha,
        lineWidth = lineWidth,
        valueLabel = valueLabel,
        title = title,
        showN = showN,
        ridgeOverlap = ridgeOverlap,
        ridgeAdjust = ridgeAdjust,
        ridgeTrim = ridgeTrim,
        ridgeMedian = ridgeMedian)

    analysis <- distRidgeClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

